/* MODULE ob04 · Bước 1 Quan sát · Đối thủ: ai đang lấy tiền của khách bạn
   9 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'ob04', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:ob04-01', skill:'insight', read:'6 phút', t:'Quán cà phê của bạn đang cạnh tranh với ai — quán bên kia đường hay ly trà sữa?',
  situation:'Bạn làm marketing cho một quán cà phê mang đi ở Quận 3, giá trung bình 35.000đ một ly. Chủ quán chỉ theo dõi hai quán cà phê cùng phố. Nhưng khảo sát nhanh 100 khách cũ đã bỏ đi cho thấy: 30 người chuyển sang quán cà phê khác, 45 người chuyển sang trà sữa hoặc nước ép, 25 người tự mang bình nước từ nhà hoặc dùng nước pha sẵn ở văn phòng.',
  concept:{ name:'Ba vòng đối thủ: trực tiếp, gián tiếp, thay thế',
    body:'<b>Đối thủ trực tiếp</b> bán cùng loại sản phẩm cho cùng khách (quán cà phê khác). <b>Đối thủ gián tiếp</b> là sản phẩm khác mà khách vẫn trả tiền cho ai đó, để làm cùng một “việc” (trà sữa cho buổi chiều tỉnh táo, cả cà phê gói mua ở siêu thị). <b>Sản phẩm thay thế</b> là cách khách tự giải mà không mua của ai (bình nước mang từ nhà). Ranh giới ba vòng không quan trọng bằng câu hỏi: khách đang “thuê” thứ gì để làm việc gì, vào lúc nào? Bằng chứng mạnh nhất là chuyển đổi thật của khách đã bỏ đi. Đừng xếp ưu tiên chỉ theo số khách: nhân số khách với mức chi của họ, rồi với phần bạn có khả năng kéo lại.' },
  example:'Trong 100 khách bỏ đi, chỉ 30 người (30%) sang đối thủ trực tiếp; 45 người (45%) sang đối thủ gián tiếp và 25 người (25%) sang sản phẩm thay thế. Giảm giá để đấu với hai quán cùng phố là nhắm vào 30% vấn đề. Nhưng khảo sát này chỉ cho biết khách đi đâu, chưa cho biết vì sao: vị, sự mới lạ hay chỗ ngồi. Bước đúng là phỏng vấn vài chục khách đã sang trà sữa về lần cuối họ mua gì thay và vì sao; có lý do rồi mới thử một món chiều và đo tỉ lệ quay lại.',
  takeaway:'Đối thủ là bất cứ ai nhận số tiền mà khách lẽ ra đã trả cho bạn, không chỉ người bán cùng món.',
  apply:'Chọn một sản phẩm bạn hay mua. Kể trong 60 giây: một đối thủ trực tiếp, một gián tiếp, một thay thế — và khi nào bạn chọn từng cái.',
  mistakes:['Chỉ liệt kê những hãng bán cùng loại sản phẩm, cùng tầm giá.','Coi cách khách tự làm lấy là “không phải đối thủ” vì không có thương hiệu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong khảo sát nhanh 100 khách cũ đã bỏ một quán cà phê, nhóm lớn nhất chuyển sang đâu?',
    options:[{k:'a',t:'Sang một quán cà phê khác giá rẻ hơn ngay gần chỗ làm của họ'},{k:'b',t:'Sang những đồ uống khác cùng giải nhu cầu buổi chiều'},
             {k:'c',t:'Ngừng hẳn việc uống đồ uống trong ngày làm việc'},{k:'d',t:'Sang chuỗi cà phê lớn vì tin tưởng thương hiệu hơn'}],
    answer:'b', why:{a:'Có, nhưng trong khảo sát chỉ 30%; đối thủ trực tiếp thường không phải phần lớn nhất.',
      b:'Đúng. Nhu cầu vẫn còn, khách chỉ đổi cách giải — 45% sang trà sữa, nước ép.',
      c:'Khảo sát không có nhóm nào bỏ hẳn: ai rời quán cũng đã có cách giải khác.',
      d:'Chuỗi lớn là đối thủ trực tiếp, nằm trong nhóm 30%.'} },
  { type:'mcq', stem:'Ngân sách quý tới chỉ đủ một bước đầu. Khảo sát cho 30/45/25 nhưng chưa biết vì sao khách sang trà sữa. Bạn làm bước nào trước?',
    options:[{k:'a',t:'Phỏng vấn 20 khách đã sang trà sữa để hỏi lý do chuyển'},{k:'b',t:'Giảm giá 15% để lấy lại khách từ hai quán cùng phố'},
             {k:'c',t:'Mở điểm bán gần văn phòng để lấy lại khách mang bình nước'},{k:'d',t:'Chạy quảng cáo so sánh chất lượng hạt với quán đối diện'}],
    answer:'a', why:{a:'Đúng. Nhóm 45% lớn nhất nhưng chưa rõ họ thuê trà sữa làm việc gì; biết lý do trước mới thử món nhỏ mà không đoán mò.',
      b:'Đánh vào nhóm 30%, lại hy sinh biên lãi, trong khi chưa biết khách đi vì giá hay vì lý do khác.',
      c:'Nhóm tự giải chỉ 25%, và chưa có dữ kiện cho thấy khoảng cách là lý do họ mang bình.',
      d:'Vẫn là cuộc đấu trong vòng trực tiếp, bỏ qua nơi tiền chảy đi nhiều nhất.'} },
  { type:'calc', stem:'Quán mất 200 khách một tháng; 45% sang đồ uống khác loại. Mỗi khách chi 35.000đ × 8 ly/tháng. Doanh thu tháng mất vào tay đối thủ gián tiếp là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:25.2, tol:0.1, wrong:[[56,'SAI_MAU_SO'],[3.15,'NGUOC_TAN_SUAT']], errors:['SAI_MAU_SO','NGUOC_TAN_SUAT'],
    steps:['Số khách sang gián tiếp = 200 × 45% = 90 khách.','Mỗi khách chi 35.000 × 8 = 280.000đ/tháng.','90 × 280.000 = 25.200.000đ = <b>25,2 triệu</b>.'] },
  { type:'mcq', stem:'Một hãng nước giải khát đóng chai nhận ra nhiều nhân viên văn phòng không mua chai nào mà mang bình cá nhân từ nhà, đổ nước máy đã đun. Đây là loại đối thủ nào?',
    options:[{k:'a',t:'Đối thủ trực tiếp, vì cùng là nước uống đóng sẵn'},{k:'b',t:'Đối thủ gián tiếp, vì có người bán sản phẩm khác cho cùng nhu cầu'},
             {k:'c',t:'Không phải đối thủ, vì nước máy gần như miễn phí'},{k:'d',t:'Sản phẩm thay thế, cách khách tự giải cơn khát'}],
    answer:'d', why:{a:'Nước tự mang từ nhà không có mặt trên kệ để cạnh tranh trực tiếp với chai nước ngọt.',
      b:'Gần đúng nhưng chưa chính xác: đối thủ gián tiếp là một sản phẩm khác mà khách vẫn phải mua của ai đó. Ở đây khách không trả tiền cho ai trong ngành.',
      c:'Miễn phí chính là lý do nó mạnh: mỗi lần khách đổ bình nước từ nhà là một chai không được bán.',
      d:'Đúng. Khách tự giải nhu cầu bằng thứ có sẵn — đó là sản phẩm thay thế.'} },
  { type:'mcq', stem:'Một ứng dụng học tiếng Anh xếp các “đối thủ” sau. Cái nào là đối thủ gián tiếp?',
    options:[{k:'a',t:'Một ứng dụng học tiếng Anh khác có giá gần bằng'},{k:'b',t:'Trung tâm tiếng Anh dạy trực tiếp buổi tối'},
             {k:'c',t:'Video miễn phí trên YouTube mà khách tự xem'},{k:'d',t:'Một ứng dụng học tiếng Nhật của cùng công ty'}],
    answer:'b', why:{a:'Cùng loại sản phẩm, cùng khách: đối thủ trực tiếp.',
      b:'Đúng. Hình thức khác (lớp học) nhưng giải cùng nhu cầu nói được tiếng Anh.',
      c:'Khách tự học bằng nguồn sẵn có gần với sản phẩm thay thế hơn.',
      d:'Nhu cầu khác (tiếng Nhật), không lấy tiền cho mục tiêu học tiếng Anh.'} },
  { type:'mcq', stem:'Chủ quán nói: “Trà sữa là khách khác, dân văn phòng uống cà phê.” Phản biện có căn cứ nhất là gì?',
    options:[{k:'a',t:'Dữ liệu cho thấy chính khách cũ của quán đang sang trà sữa'},{k:'b',t:'Trà sữa đang là xu hướng chung của giới trẻ nên sớm muộn quán cũng phải bán'},
             {k:'c',t:'Dân văn phòng ngày càng trẻ nên thích đồ ngọt hơn'},{k:'d',t:'Các chuỗi lớn đều bán cả trà sữa lẫn cà phê'}],
    answer:'a', why:{a:'Đúng. Bằng chứng là hành vi của chính khách quán, không phải cảm nhận.',
      b:'Chạy theo xu hướng không phải lập luận về đối thủ.',
      c:'Một nhận định chung chung, chưa có dữ kiện.',
      d:'Việc người khác làm không chứng minh khách của quán này đang chuyển.'} },
  { type:'mcq', stem:'Giả định minh hoạ: 30 khách sang quán khác (8 ly/tháng, 35.000đ), quán kéo lại được khoảng 1/3. 45 khách sang trà sữa (4 ly/tháng, 35.000đ), quán chỉ kéo lại được khoảng 1/10. Nên ưu tiên nhóm nào?',
    options:[{k:'a',t:'Nhóm sang trà sữa, vì đông người nhất nên mất nhiều nhất'},{k:'b',t:'Cả hai ngang nhau, vì mỗi ly đều có giá 35.000đ như nhau'},
             {k:'c',t:'Nhóm sang quán khác, vì tiền lấy lại được gấp hơn 4 lần'},{k:'d',t:'Chưa nhóm nào, vì khảo sát 100 khách là quá ít để chọn'}],
    answer:'c', why:{a:'Đông người chưa phải nhiều tiền: 45 × 4 × 35.000 = 6,3 triệu mỗi tháng, thấp hơn 8,4 triệu của nhóm kia, và khả năng kéo lại cũng thấp hơn.',
      b:'Giá mỗi ly bằng nhau nhưng số ly và khả năng kéo lại khác nhau; so tiền lấy lại được thì khác xa.',
      c:'Đúng. 30 × 8 × 35.000 × 1/3 ≈ 2,8 triệu mỗi tháng, so với 6,3 triệu × 1/10 ≈ 0,63 triệu: gấp hơn 4 lần.',
      d:'Khảo sát nhỏ nên thử từng bước nhỏ, nhưng vẫn đủ để xếp thứ tự ưu tiên; chờ mẫu lớn là trì hoãn.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:ob04-02', skill:'insight', read:'7 phút', t:'Vẽ bản đồ đối thủ thế nào để thấy chỗ trống?',
  situation:'Bạn làm cho một thương hiệu bánh mì que mới ở Hà Nội. Trên thị trường có 8 thương hiệu bánh ăn sáng mang đi. Nhóm liệt kê cả 8 vào một bảng Excel 12 cột nhưng không ai rút ra được gì. Sếp yêu cầu: “Cho anh một hình, nhìn là biết mình nên đứng ở đâu.”',
  concept:{ name:'Bản đồ định vị hai trục',
    body:'Chọn <b>hai trục khách dùng để cân nhắc khi mua</b>, rút từ vài cuộc phỏng vấn (“khi chọn bánh sáng, hai điều bạn nghĩ tới đầu tiên?”) chứ không từ điều hãng thích nói. Đặt từng đối thủ lên đó theo dữ kiện: giá niêm yết, thành phần, lời hứa trên bao bì. Hai bản đồ cùng ngành nhưng khác trục cho hai kết luận khác nhau: bản đồ giá chỉ cho thấy ai đắt ai rẻ, bản đồ nhận thức cho thấy khách xếp ai gần ai. Chỗ đông là nơi cạnh tranh bằng giá; chỗ trống chỉ là giả thuyết: có thể là cơ hội, có thể là nơi không có khách, hoặc nơi làm không ra lãi.' },
  example:'Trục ngang: giá, từ 10.000đ đến 40.000đ. Trục dọc: “ăn nhanh” đến “ăn no, đủ chất”. 5 trên 8 hãng dồn ở góc giá 12.000–18.000đ, ăn nhanh. Góc 25.000–30.000đ, đủ chất chỉ có 1 hãng. Trước khi nhảy vào, nhóm kiểm tra: khảo sát 60 người đi làm, 21 người (35%) nói sẵn sàng trả trên 25.000đ cho bữa sáng no đến trưa. Đó mới là tín hiệu, chưa phải khách thật: nói ra khác với trả tiền. Bước tiếp theo là bán thử hoặc nhận đặt cọc, và tính xem bánh 28.000đ có còn lãi không.',
  takeaway:'Bản đồ tốt dùng hai trục khách thật sự cân nhắc; chỗ trống chỉ đáng giá khi có khách đứng ở đó.',
  apply:'Vẽ bản đồ hai trục cho 5 hãng nước giải khát bạn biết. Nói trong 60 giây vì sao chọn hai trục đó.',
  mistakes:['Chọn trục theo điều hãng muốn khoe (ví dụ “sáng tạo”) thay vì điều khách cân nhắc.','Thấy chỗ trống là lao vào, không kiểm tra có khách ở đó hay không.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trên bản đồ đối thủ, một góc hoàn toàn trống thường có nghĩa là gì?',
    options:[{k:'a',t:'Một cơ hội rõ ràng mà các hãng khác chưa nhìn ra'},{k:'b',t:'Có thể là cơ hội, cũng có thể là nơi không có khách'},
             {k:'c',t:'Luật pháp hoặc chi phí sản xuất chặn các hãng vào'},{k:'d',t:'Bản đồ bị vẽ sai trục nên số liệu bị lệch sang bên'}],
    answer:'b', why:{a:'Nhiều góc trống vì không ai muốn mua ở đó.',
      b:'Đúng. Chỗ trống là giả thuyết, cần dữ kiện về khách để xác nhận.',
      c:'Có thể xảy ra nhưng không phải cách đọc mặc định.',
      d:'Trục sai là một khả năng, nhưng góc trống không tự chứng minh điều đó.'} },
  { type:'mcq', stem:'Phỏng vấn 10 người đi làm: 8 người nói bữa sáng phải “no đến trưa” họ mới chịu trả thêm. Bạn đã có trục ngang là giá. Bạn chọn trục dọc nào?',
    options:[{k:'a',t:'Độ tiện: số điểm bán gần nơi khách đi làm'},{k:'b',t:'Độ lành mạnh: mức ít đường, ít dầu mỡ của thành phần'},
             {k:'c',t:'Độ no: bữa sáng giữ khách no được đến mấy giờ'},{k:'d',t:'Độ ngon: điểm đánh giá trung bình trên ứng dụng giao đồ ăn'}],
    answer:'c', why:{a:'Độ tiện là yếu tố có thật, nhưng phỏng vấn không cho thấy nó phân hoá việc khách trả thêm tiền.',
      b:'Lành mạnh là điều hãng hay muốn nói; 8/10 người đã nêu độ no, không phải thành phần.',
      c:'Đúng. Trục rút từ điều khách tự nói khi cân nhắc mua và gắn với việc chịu trả giá cao hơn.',
      d:'Điểm đánh giá khó so giữa hãng khác nhau và không giải thích lý do khách chịu trả thêm.'} },
  { type:'calc', stem:'Khảo sát 60 người đi làm, 21 người sẵn sàng trả trên 25.000đ cho bữa sáng no đến trưa. Tỉ lệ đó là bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.1, wrong:[[285.7,'SAI_MAU_SO'],[21,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = số người đồng ý ÷ tổng số người được hỏi.','21 ÷ 60 = 0,35 = <b>35%</b>.'] },
  { type:'mcq', stem:'5 trên 8 hãng dồn ở góc giá rẻ, ăn nhanh. Hãng thứ 6 muốn vào góc này. Điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Phải cạnh tranh chủ yếu bằng giá và độ phủ điểm bán'},{k:'b',t:'Dễ thắng vì góc đông chứng tỏ khách mua rất nhiều'},
             {k:'c',t:'Các hãng cũ sẽ rút lui để tránh chiến tranh giá'},{k:'d',t:'Khách sẽ tò mò thử hãng mới vì thấy lạ trên kệ'}],
    answer:'a', why:{a:'Đúng. Khi các hãng giống nhau, khách chọn theo giá và theo cái nằm gần tay.',
      b:'Góc đông có nhiều khách nhưng cũng chia cho nhiều người.',
      c:'Hãng cũ thường giữ chỗ, không tự rút.',
      d:'Sự tò mò có, nhưng không đủ giữ khách khi sản phẩm giống hệt.'} },
  { type:'mcq', stem:'Tình huống mới: bản đồ mỹ phẩm có góc “giá cao, không mùi hương” trống. Bước tiếp theo hợp lý nhất?',
    options:[{k:'a',t:'Ra ngay dòng sản phẩm giá cao không mùi để chiếm chỗ'},{k:'b',t:'Hỏi đội thiết kế ngay xem bao bì cao cấp không mùi nên trông ra sao cho sang'},
             {k:'c',t:'Đổi trục bản đồ để góc đó không còn trống nữa'},{k:'d',t:'Tìm bằng chứng có nhóm khách cần và chịu trả mức giá đó'}],
    answer:'d', why:{a:'Nhảy vào trước khi kiểm tra có khách là đặt cược mù.',
      b:'Bao bì là việc sau khi biết có thị trường.',
      c:'Đổi trục để giấu câu hỏi không giúp ra quyết định.',
      d:'Đúng. Chỗ trống cần được xác nhận bằng khách thật.'} },
  { type:'mcq', stem:'Đặt đối thủ lên bản đồ nên dựa vào đâu?',
    options:[{k:'a',t:'Cảm nhận chung của nhóm marketing về từng hãng'},{k:'b',t:'Giá niêm yết, thành phần và lời hứa hãng công bố'},
             {k:'c',t:'Số lượt thích trên bài đăng gần nhất của mỗi hãng'},{k:'d',t:'Lời kể của nhân viên bán hàng về độ hot của hãng'}],
    answer:'b', why:{a:'Cảm nhận nội bộ dễ thiên vị hãng mình.',
      b:'Đúng. Dữ kiện kiểm chứng được giúp bản đồ đáng tin.',
      c:'Lượt thích đo sự chú ý, không đo vị trí giá hay nhu cầu.',
      d:'Có ích làm gợi ý, nhưng cần đối chiếu dữ kiện.'} },
  { type:'mcq', stem:'Nhóm A vẽ bản đồ bánh ăn sáng theo giá × độ no, nhóm B theo giá × độ sang của bao bì. B thấy góc “giá cao, bao bì sang” trống và muốn vào. Vì sao kết luận của B kém tin cậy hơn?',
    options:[{k:'a',t:'Khách chưa chứng tỏ họ chọn bữa sáng theo độ sang bao bì'},{k:'b',t:'Giá cao luôn bán kém hơn giá thấp ở ngành bánh ăn sáng'},
             {k:'c',t:'Hai nhóm dùng hai trục khác nhau nên không thể cùng đúng'},{k:'d',t:'Nhóm B nên vẽ thêm nhiều đối thủ để góc đó đủ dữ liệu'}],
    answer:'a', why:{a:'Đúng. Trục phải là điều khách cân nhắc; chỗ trống trên trục khách không dùng chỉ là khoảng trống vô nghĩa.',
      b:'Không có quy luật như vậy; nhiều ngành có nhóm khách chịu trả giá cao.',
      c:'Hai bản đồ khác trục có thể cùng đúng, mỗi bản đồ cho thấy một lát cắt; vấn đề là trục B không rút từ khách.',
      d:'Thêm đối thủ không sửa được việc trục chọn sai; số điểm nhiều hơn vẫn nằm trên trục sai.'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:ob04-03', skill:'creative', read:'7 phút', t:'Đối thủ đang chạy quảng cáo gì — và nó nói lên điều gì?',
  situation:'Bạn làm cho một thương hiệu kem chống nắng nội địa. Đối thủ chính vừa tăng mạnh hiện diện trên Facebook. Bạn mở Thư viện quảng cáo của Meta (Meta Ad Library), gõ tên trang đối thủ và thấy 24 quảng cáo đang chạy. Sếp hỏi: “Họ đang làm gì, mình có cần phản ứng không?”',
  concept:{ name:'Đọc thư viện quảng cáo như đọc chiến lược',
    body:'Thư viện quảng cáo Meta cho mọi người xem các quảng cáo đang chạy của một trang, kèm ngày bắt đầu. Đừng đọc từng mẫu cho vui; hãy <b>đếm và phân loại</b>: bao nhiêu mẫu nói về thông điệp nào, bao nhiêu mẫu đã chạy lâu. Mẫu chạy lâu thường là mẫu hiệu quả, vì không ai trả tiền lâu cho mẫu kém. Thông điệp lặp nhiều là điều đối thủ đặt cược. Đây là tín hiệu, không phải số liệu doanh thu.' },
  example:'Trong 24 mẫu: 14 mẫu nói “không bết dính, đi làm cả ngày”, 6 mẫu nói về giảm giá, 4 mẫu nói về thành phần. 5 mẫu chạy trên 60 ngày, và cả 5 đều thuộc nhóm “không bết dính”. Cách đọc: đối thủ đã thử nhiều hướng và đang dồn tiền vào lợi ích cảm giác khi dùng, chứ không phải giá. Nếu thương hiệu của bạn cũng mạnh về kết cấu nhẹ, bạn cần một cách nói khác để không trông như bản sao.',
  takeaway:'Đếm thông điệp và tìm mẫu chạy lâu: đó là nơi đối thủ đang đặt tiền thật.',
  points:["Quảng cáo chạy lâu là quảng cáo đang được nuôi, vì người trả tiền theo dõi kết quả. Thời gian chạy là bằng chứng gián tiếp về hiệu quả, rẻ hơn nhiều so với đoán.","Gom mẫu theo thông điệp biến một đống ảnh thành bảng đếm. Tỷ trọng thông điệp cho thấy đối thủ nghĩ khách quan tâm gì, chứ không cho biết mẫu nào đẹp nhất.","Kết quả chỉ nên làm giả thuyết để bạn thử, không phải bản mẫu để sao chép. Hiểu họ nhấn vào đâu giúp bạn chọn góc khác, nơi khách chưa nghe ai nói."],
  counter:"Biến thể: trang của đối thủ mới mở nên chưa mẫu nào chạy quá vài tuần. Bạn không thể phân biệt mẫu hiệu quả với mẫu mới đăng. Dấu hiệu nhận ra: ngày bắt đầu gần nhau, không mẫu nào chạy lâu, thông điệp rải đều giữa nhiều hướng. Khi đó thư viện chỉ cho biết họ đang thử. Hãy quay lại sau vài tuần, đánh dấu mẫu nào còn sống rồi mới kết luận.",
  deeper:"Người làm nghề nhớ rằng thư viện chỉ cho thấy quảng cáo, không cho thấy chi tiêu, đối tượng hay doanh thu. Mẫu chạy lâu có thể là mẫu rẻ để duy trì, hoặc chưa ai nhớ tắt. Đánh đổi nằm ở thời gian ngồi đếm so với việc phản ứng theo cảm tính. Khái niệm kề cận là định vị: nếu đối thủ đã chiếm một góc, bạn nên tránh hay tranh. Tín hiệu theo dõi là thông điệp mới xuất hiện và mẫu bị tắt. Phép kiểm tra trong tuần: <b>chụp bảng đếm hôm nay, quay lại sau bảy ngày</b>, ghi mẫu nào mới, mẫu nào đã tắt, rồi so với dự đoán ban đầu.",
  apply:'Mở Thư viện quảng cáo Meta, chọn một thương hiệu bạn biết. Đếm 10 mẫu theo thông điệp và nói trong 60 giây họ đang đặt cược vào điều gì.',
  mistakes:['Chọn một mẫu quảng cáo đẹp nhất rồi kết luận đó là chiến lược.','Coi số mẫu quảng cáo như ngân sách hoặc doanh thu của đối thủ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong thư viện quảng cáo, mẫu nào thường cho biết nhiều nhất về điều đối thủ thấy hiệu quả?',
    options:[{k:'a',t:'Mẫu có hình ảnh đẹp và đầu tư công phu nhất'},{k:'b',t:'Mẫu mới được đăng trong tuần này, cập nhật nhất'},
             {k:'c',t:'Mẫu đã chạy liên tục trong thời gian dài'},{k:'d',t:'Mẫu có người nổi tiếng xuất hiện trong ảnh'}],
    answer:'c', why:{a:'Đẹp không có nghĩa là bán được.',
      b:'Mẫu mới thường còn đang thử nghiệm.',
      c:'Đúng. Không ai trả tiền lâu cho một mẫu kém.',
      d:'Người nổi tiếng tốn tiền, nhưng không chứng minh hiệu quả.'} },
  { type:'mcq', stem:'Đối thủ đang dồn tiền vào thông điệp “không bết dính”, và sản phẩm của bạn cũng nhẹ. Bạn chọn cách nói nào?',
    options:[{k:'a',t:'Nói “không bết dính” to hơn, chạy nhiều ngân sách hơn họ'},{k:'b',t:'Chuyển hẳn sang quảng cáo giảm giá để khác biệt'},
             {k:'c',t:'Sao chép cấu trúc mẫu chạy lâu nhất của đối thủ vì đó là mẫu đã được thị trường kiểm chứng'},{k:'d',t:'Nói lợi ích nhẹ bằng bối cảnh riêng, ví dụ đi xe máy trưa nắng'}],
    answer:'d', why:{a:'Lặp cùng câu chỉ làm khách nhớ hãng đã nói trước.',
      b:'Bỏ điểm mạnh thật để đấu giá là tự làm mỏng lãi.',
      c:'Bản sao sẽ bị nhận ra và nhắc khách nhớ tới đối thủ.',
      d:'Đúng. Giữ lợi ích thật nhưng gắn với một bối cảnh mà đối thủ chưa chiếm.'} },
  { type:'calc', stem:'Đối thủ có 24 mẫu đang chạy, 14 mẫu nói về “không bết dính”. Thông điệp này chiếm bao nhiêu phần trăm số mẫu?',
    unit:'%', ans:58.3, tol:0.2, wrong:[[171.4,'SAI_MAU_SO'],[14,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = số mẫu của thông điệp ÷ tổng số mẫu.','14 ÷ 24 ≈ 0,583 = <b>58,3%</b>.'] },
  { type:'mcq', stem:'Đối thủ có 24 mẫu, bạn có 8 mẫu. Kết luận nào không có căn cứ?',
    options:[{k:'a',t:'Đối thủ đang thử nghiệm nhiều hướng thông điệp hơn'},{k:'b',t:'Đối thủ chi gấp ba lần ngân sách quảng cáo của bạn'},
             {k:'c',t:'Đối thủ có nhiều mẫu sáng tạo đang hoạt động hơn'},{k:'d',t:'Đối thủ đang tích cực hơn trên Facebook lúc này'}],
    answer:'b', why:{a:'Nhiều mẫu thường đi cùng nhiều thử nghiệm; có căn cứ.',
      b:'Đúng, đây là kết luận không có căn cứ: số mẫu không cho biết mỗi mẫu tiêu bao nhiêu.',
      c:'Đó chỉ là mô tả đúng dữ kiện.',
      d:'Số mẫu đang chạy là tín hiệu hợp lý về mức hoạt động.'} },
  { type:'mcq', stem:'Tình huống mới: một chuỗi trà sữa chạy 10 mẫu, 8 mẫu bắt đầu cùng ngày và đều về món mới. Đọc thế nào?',
    options:[{k:'a',t:'Họ đang ra mắt món mới và thử nhiều cách giới thiệu'},{k:'b',t:'Món cũ bán kém nên họ phải bỏ hẳn dòng món cũ và dồn hết tiền vào món mới'},
             {k:'c',t:'Họ đang gặp khủng hoảng truyền thông cần che đi'},{k:'d',t:'Họ đang cắt giảm quảng cáo nên dồn vào một đợt'}],
    answer:'a', why:{a:'Đúng. Nhiều mẫu cùng ngày, cùng chủ đề là dấu hiệu một đợt ra mắt có thử nghiệm.',
      b:'Không có dữ kiện nào về doanh số món cũ.',
      c:'Suy diễn tiêu cực không có căn cứ.',
      d:'Nhiều mẫu cùng lúc khó là dấu hiệu cắt giảm.'} },
  { type:'mcq', stem:'Vì sao nên đếm và phân loại cả 24 mẫu thay vì xem vài mẫu nổi bật?',
    options:[{k:'a',t:'Vì Meta chỉ cho xem hết khi người xem cuộn đến cuối'},{k:'b',t:'Vì các mẫu nổi bật thường đã hết hạn chạy từ lâu'},
             {k:'c',t:'Vì cần đủ số mẫu mới được báo cáo cho quản lý'},{k:'d',t:'Vì tỉ lệ thông điệp mới cho thấy họ đặt cược vào đâu'}],
    answer:'d', why:{a:'Đó không phải lý do phân tích.',
      b:'Mẫu nổi bật vẫn có thể đang chạy.',
      c:'Mục đích là hiểu đối thủ, không phải đủ thủ tục.',
      d:'Đúng. Một mẫu là giai thoại; tỉ lệ trên tổng là chiến lược.'} },
  { type:'mcq', stem:'Điều gì Thư viện quảng cáo Meta không cho bạn biết một cách đáng tin về đối thủ thương mại?',
    options:[{k:'a',t:'Mẫu quảng cáo đó mang lại bao nhiêu đơn hàng'},{k:'b',t:'Nội dung chữ và hình ảnh của từng mẫu quảng cáo'},
             {k:'c',t:'Ngày bắt đầu chạy của từng mẫu đang hoạt động'},{k:'d',t:'Trang nào đang đứng tên chạy các mẫu đó'}],
    answer:'a', why:{a:'Đúng. Hiệu quả bán hàng là dữ liệu nội bộ của đối thủ.',
      b:'Nội dung được hiển thị công khai.',
      c:'Ngày bắt đầu có hiển thị; đó là manh mối quan trọng.',
      d:'Tên trang là thông tin cơ bản của thư viện.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:ob04-04', skill:'measure', read:'7 phút', t:'Giá niêm yết của đối thủ có phải giá khách thật sự trả?',
  situation:'Bạn bán nồi chiên không dầu trên Shopee với giá 1.290.000đ. Đối thủ niêm yết 1.390.000đ, cao hơn bạn 100.000đ, nhưng họ vẫn bán nhiều hơn. Sếp nghĩ khách không nhạy giá. Bạn quyết định ghi lại mọi khuyến mãi của đối thủ trong 4 tuần trước khi kết luận.',
  concept:{ name:'Giá thực trả (net price)',
    body:'Giá khách thật sự trả = giá niêm yết − mọi khoản giảm: mã giảm của shop, voucher sàn, quà tặng quy ra tiền, miễn phí vận chuyển. So sánh giá với đối thủ phải so <b>giá thực trả</b>, không phải giá trên nhãn. Cách làm: theo dõi đều đặn, ghi vào một bảng theo ngày, vì khuyến mãi thay đổi theo đợt (ngày đôi, cuối tháng).' },
  example:'Đối thủ niêm yết 1.390.000đ, có mã giảm 150.000đ, tặng bộ giấy lót trị giá 60.000đ và miễn phí vận chuyển 30.000đ. Giá thực trả tương đương 1.390.000 − 150.000 − 60.000 − 30.000 = 1.150.000đ. Bên bạn: 1.290.000đ, khách tự trả 30.000đ vận chuyển → 1.320.000đ. Thực tế đối thủ rẻ hơn 170.000đ. Khách vẫn nhạy giá; bạn chỉ đang nhìn nhầm con số.',
  takeaway:'Đừng so nhãn giá — hãy so số tiền khách thật sự bỏ ra sau mọi khuyến mãi.',
  points:["Khách cuối cùng nhìn ô tổng tiền ở bước thanh toán, không nhìn giá niêm yết. Phép tính phải khớp với đúng ô đó, gồm cả mã giảm, quà và phí ship.","Quà tặng cần quy ra tiền theo giá khách có thể quy đổi, không theo giá bạn nhập. Phần quà khách không dùng thì không làm giá thực trả thấp đi.","Khuyến mãi thay đổi theo đợt, nên một lần kiểm tra chỉ là ảnh chụp. Bảng theo dõi theo ngày cho thấy mức giá thường và mức giá đợt, hai thứ khách nhớ khác nhau."],
  counter:"Biến thể: đối thủ có giá thực trả thấp hơn bạn nhưng đánh giá của họ nhấn vào “giao chậm” và “thiếu phụ kiện”. Nếu chỉ so giá thực trả, bạn kết luận khách chạy theo giá rẻ. Dấu hiệu nhận ra: đơn của đối thủ vẫn nhiều nhưng tỉ lệ mua lại thấp, nhiều đánh giá trách dịch vụ. Khi đó giá chưa phải toàn bộ lý do, hãy so thêm tốc độ giao và bảo hành.",
  deeper:"Người làm nghề nhớ rằng giá thực trả là thứ khách thấy, còn lãi của đối thủ là thứ bạn không thấy. Họ có thể đang chịu lỗ để lấy thị phần, hoặc có chi phí thấp hơn nhờ nhập nhiều. Đánh đổi nằm ở chỗ đuổi theo mức giảm của họ có thể làm bạn mất lãi gộp trong khi họ vẫn trụ được. Khái niệm kề cận là phản ứng giảm giá và giá trị cảm nhận. Tín hiệu theo dõi: các đợt giảm lặp lại vào ngày đôi. Phép kiểm tra trong tuần: <b>lập bảng ba cột gồm niêm yết, các khoản giảm và giá thực trả</b>, ghi hai lần cách nhau vài ngày.",
  apply:'Chọn một sản phẩm trên sàn, tìm hai shop bán. Tính giá thực trả của mỗi bên và nói trong 60 giây bên nào rẻ hơn thật.',
  mistakes:['So giá niêm yết rồi kết luận khách không quan tâm giá.','Chỉ kiểm tra khuyến mãi một ngày rồi coi là giá thường xuyên.'],
  q:[
  { type:'mcq', stem:'Đoán trước: đối thủ niêm yết cao hơn bạn 100.000đ nhưng bán chạy hơn. Khả năng nào nên kiểm tra đầu tiên?',
    options:[{k:'a',t:'Khách tin rằng giá cao hơn thì chất lượng tốt hơn'},{k:'b',t:'Đối thủ có nhiều đánh giá năm sao hơn bạn rất nhiều'},
             {k:'c',t:'Sau khuyến mãi, giá khách trả cho đối thủ thấp hơn'},{k:'d',t:'Sàn đang ưu tiên hiển thị sản phẩm đắt tiền hơn'}],
    answer:'c', why:{a:'Có thể, nhưng cần loại trừ chuyện giá thực trước.',
      b:'Đánh giá quan trọng, nhưng kiểm tra giá thực rẻ và nhanh hơn.',
      c:'Đúng. Khuyến mãi làm nhãn giá sai lệch; kiểm tra điều này trước.',
      d:'Không có căn cứ rằng sàn ưu tiên sản phẩm đắt.'} },
  { type:'mcq', stem:'Sau khi tính ra đối thủ rẻ hơn 170.000đ, bạn đề xuất gì với sếp trước tiên?',
    options:[{k:'a',t:'Hạ ngay giá niêm yết xuống thấp hơn đối thủ 50.000đ để không mất thêm khách trên sàn'},{k:'b',t:'Theo dõi thêm để biết khuyến mãi đó là thường xuyên hay theo đợt'},
             {k:'c',t:'Tăng giá niêm yết để trông cao cấp hơn đối thủ'},{k:'d',t:'Giữ nguyên vì khách vẫn mua đều mỗi ngày như cũ'}],
    answer:'b', why:{a:'Phản ứng khi chưa biết khuyến mãi của họ kéo dài bao lâu.',
      b:'Đúng. Một khuyến mãi theo đợt và một giá thường xuyên cần hai cách đối phó khác nhau.',
      c:'Đi ngược dữ kiện cho thấy khách đang nhạy giá.',
      d:'Bạn đang thua về doanh số; giữ nguyên là bỏ qua vấn đề.'} },
  { type:'calc', stem:'Đối thủ niêm yết 1.390.000đ, mã giảm 150.000đ, quà trị giá 60.000đ, miễn phí vận chuyển 30.000đ. Giá thực trả tương đương là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:1150, tol:1, wrong:[[1240,'QUEN_CHI_PHI_KHUYEN_MAI'],[1210,'QUEN_CHI_PHI_KHUYEN_MAI']], errors:['QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Cộng mọi khoản giảm: 150 + 60 + 30 = 240 nghìn.','1.390 − 240 = <b>1.150 nghìn đồng</b>.'] },
  { type:'calc', stem:'Bạn bán 1.290.000đ, khách tự trả 30.000đ vận chuyển; giá thực của đối thủ là 1.150.000đ. Đối thủ rẻ hơn bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:170, tol:1, wrong:[[140,'SAI_TINH_TOAN'],[-100,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Giá thực của bạn = 1.290 + 30 = 1.320 nghìn.','1.320 − 1.150 = <b>170 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Tình huống mới: đối thủ chỉ giảm sâu vào ngày 9/9, 10/10, 11/11. Bạn nên ghi nhận điều này ra sao trong bảng theo dõi?',
    options:[{k:'a',t:'Tính giá ngày đôi như giá chuẩn của đối thủ từ nay'},{k:'b',t:'Bỏ qua các ngày đôi vì đó chỉ là dịp đặc biệt'},
             {k:'c',t:'Lấy trung bình các ngày và dùng một con số đại diện'},{k:'d',t:'Ghi riêng giá ngày thường và giá ngày đôi, đi kèm lịch'}],
    answer:'d', why:{a:'Làm bạn tưởng đối thủ lúc nào cũng rẻ.',
      b:'Ngày đôi có thể chiếm phần lớn doanh số tháng; không thể bỏ qua.',
      c:'Con số trung bình che mất nhịp khuyến mãi mà bạn cần đối phó.',
      d:'Đúng. Hai mức giá, hai cách phản ứng khác nhau.'} },
  { type:'mcq', stem:'Vì sao quà tặng nên được quy ra tiền khi so giá?',
    options:[{k:'a',t:'Vì khách coi quà là một phần giá trị họ nhận được'},{k:'b',t:'Vì sàn thương mại điện tử bắt buộc ghi giá trị quà'},
             {k:'c',t:'Vì quà tặng được tính bằng đúng giá bán lẻ của nó'},{k:'d',t:'Vì quà tặng giúp đối thủ được miễn thuế nhiều hơn'}],
    answer:'a', why:{a:'Đúng. Khách so tổng giá trị nhận được với số tiền bỏ ra.',
      b:'Không phải lý do phân tích.',
      c:'Giá trị cảm nhận có thể thấp hơn giá bán lẻ; nên quy đổi thận trọng.',
      d:'Không liên quan đến so sánh giá.'} },
  { type:'mcq', stem:'Theo dõi giá đối thủ bao lâu một lần là hợp lý với hàng bán trên sàn?',
    options:[{k:'a',t:'Một lần mỗi quý, khi cả nhóm ngồi lập kế hoạch kinh doanh cho quý tiếp theo'},{k:'b',t:'Đều đặn hằng tuần, và dày hơn quanh các đợt sale lớn'},
             {k:'c',t:'Chỉ khi thấy doanh số của mình giảm rõ rệt'},{k:'d',t:'Một lần khi mới ra mắt sản phẩm là đủ'}],
    answer:'b', why:{a:'Giá trên sàn đổi nhanh hơn nhiều so với chu kỳ quý.',
      b:'Đúng. Khuyến mãi sàn thay đổi theo tuần và theo đợt.',
      c:'Khi đó bạn đã mất khách rồi mới biết.',
      d:'Giá đối thủ không đứng yên sau ngày ra mắt.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:ob04-05', skill:'brand', read:'7 phút', t:'Điểm mạnh nhất của đối thủ đang che giấu điểm yếu nào?',
  situation:'Bạn làm cho một chuỗi phòng tập nhỏ ở Đà Nẵng, 2 cơ sở. Đối thủ là một chuỗi lớn với 15 cơ sở, máy tập hiện đại, giá hội viên 700.000đ/tháng. Nhóm bạn cảm thấy không có cửa. Nhưng các đánh giá trên Google Maps của đối thủ lặp lại một phàn nàn: đông, phải chờ máy giờ cao điểm.',
  concept:{ name:'Mặt trái của điểm mạnh',
    body:'Điểm mạnh lớn của đối thủ thường kèm một <b>cái giá</b> khó bỏ: chuỗi lớn thì đông và khó cá nhân hoá, rẻ thì khó phục vụ kỹ. Đó là chỗ hãng nhỏ có thể đứng, nhưng không tuyệt đối: đối thủ vẫn có thể tách thương hiệu riêng hoặc mở rộng thêm. Vì vậy cần hai bước. Một, mã hoá vài chục đến vài trăm đánh giá thành chủ đề, đếm tỉ lệ và phân biệt lỗi cấu trúc (đông vì mô hình cần nhiều hội viên) với lỗi vận hành (nhân viên lơ là, sửa được trong tuần). Hai, tính xem lời hứa của bạn có đủ tiền sống không.' },
  example:'Bạn mã hoá 200 đánh giá gần nhất của đối thủ: 64 đánh giá (32%) nhắc đông và chờ máy từ 17 giờ đến 20 giờ, 20 nhắc nhân viên, phần còn lại là giá, vệ sinh, máy hỏng. Đông là lỗi cấu trúc: chuỗi sống nhờ nhiều hội viên, giới hạn là tự cắt doanh thu. Lời hứa của bạn: giới hạn 150 hội viên mỗi cơ sở, đặt lịch máy trước. Kiểm tra kinh tế (số minh hoạ): 150 × 700.000đ = 105 triệu mỗi tháng; mặt bằng, huấn luyện viên, điện khoảng 80 triệu, còn 25 triệu mỗi cơ sở. Hoà vốn ở 115 hội viên, nên giới hạn 150 còn đệm. Nếu không đủ, đổi lời hứa trước khi chọn.',
  takeaway:'Đừng đấu vào điểm mạnh của đối thủ; hãy đứng ở cái giá mà điểm mạnh đó buộc họ phải trả.',
  apply:'Chọn một thương hiệu dẫn đầu mà bạn biết. Nói trong 60 giây: điểm mạnh lớn nhất của họ là gì và cái giá đi kèm là gì.',
  mistakes:['Tìm điểm yếu ngẫu nhiên của đối thủ (ví dụ một lần phục vụ kém) thay vì điểm yếu gắn với cấu trúc.','Chọn đấu thẳng vào điểm mạnh nhất vì nghĩ “phải hơn họ ở mọi mặt”.'],
  q:[
  { type:'mcq', stem:'Đoán trước: một chuỗi phòng tập 15 cơ sở, giá rẻ. Điểm yếu nào khó sửa nhất với họ?',
    options:[{k:'a',t:'Máy tập ở một vài cơ sở đã cũ, hay hỏng và bị khách phàn nàn nhiều trên mạng'},{k:'b',t:'Nhân viên lễ tân chưa thật sự niềm nở với khách'},
             {k:'c',t:'Đông khách giờ cao điểm vì mô hình cần nhiều hội viên'},{k:'d',t:'Fanpage cập nhật bài đăng chưa đều đặn mỗi tuần'}],
    answer:'c', why:{a:'Mua máy mới là việc họ làm được nhanh.',
      b:'Đào tạo lại nhân viên là việc sửa được.',
      c:'Đúng. Giảm đông là giảm hội viên, tức là làm yếu chính mô hình kinh doanh của họ.',
      d:'Việc nhỏ, sửa trong một tuần.'} },
  { type:'mcq', stem:'Bạn chọn lời hứa chính nào cho phòng tập 2 cơ sở của mình?',
    options:[{k:'a',t:'Máy tập mới nhất thành phố, hàng nhập khẩu chính hãng'},{k:'b',t:'Giá hội viên rẻ hơn đối thủ 100.000đ mỗi tháng'},
             {k:'c',t:'Nhiều lớp nhóm hơn với đa dạng bộ môn mỗi tuần'},{k:'d',t:'Giới hạn hội viên, đặt lịch máy trước, không phải chờ'}],
    answer:'d', why:{a:'Đấu vào đúng điểm mạnh của chuỗi lớn, bạn có ít tiền hơn.',
      b:'Chuỗi lớn có quy mô để giảm giá theo, bạn thì không.',
      c:'Chuỗi 15 cơ sở dễ có nhiều lớp hơn bạn.',
      d:'Đúng. Đứng đúng chỗ mặt trái của quy mô, nơi họ khó theo.'} },
  { type:'calc', stem:'Trong 200 đánh giá gần nhất của đối thủ, 64 đánh giá than phiền chuyện đông. Tỉ lệ là bao nhiêu phần trăm?',
    unit:'%', ans:32, tol:0.1, wrong:[[312.5,'SAI_MAU_SO'],[64,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = số đánh giá than phiền ÷ tổng số đánh giá.','64 ÷ 200 = 0,32 = <b>32%</b>.'] },
  { type:'mcq', stem:'Tình huống mới: một hãng sữa hạt cao cấp mạnh ở nguyên liệu nhập khẩu, giá 65.000đ/hộp. Mặt trái nào hãng nội có thể đứng?',
    options:[{k:'a',t:'Giá cao nên khó thành thói quen uống hằng ngày'},{k:'b',t:'Bao bì chưa bắt mắt bằng các hãng quốc tế khác'},
             {k:'c',t:'Hãng chưa có nhiều người nổi tiếng quảng bá'},{k:'d',t:'Hãng chưa có mặt ở nhiều tỉnh miền Tây'}],
    answer:'a', why:{a:'Đúng. Chuỗi suy luận: nguyên liệu nhập khẩu kéo chi phí, nên giá 65.000đ/hộp, nên ít người uống mỗi ngày. Hãng nội có thể hứa “uống mỗi ngày”, miễn là giá hợp lý tính ra được.',
      b:'Bao bì có thể sửa; không gắn với điểm mạnh cốt lõi.',
      c:'Không phải cái giá của điểm mạnh nguyên liệu.',
      d:'Độ phủ là chuyện phân phối, có thể mở rộng.'} },
  { type:'mcq', stem:'Vì sao nên đọc phàn nàn lặp lại thay vì một vài đánh giá rất gay gắt?',
    options:[{k:'a',t:'Vì đánh giá gay gắt thường là đối thủ viết để phá'},{k:'b',t:'Vì phàn nàn lặp lại cho thấy vấn đề của mô hình'},
             {k:'c',t:'Vì Google Maps ẩn các đánh giá gay gắt đi sau vài ngày'},{k:'d',t:'Vì phàn nàn lặp lại thường ngắn nên đọc nhanh hơn'}],
    answer:'b', why:{a:'Không có căn cứ để quy kết như vậy.',
      b:'Đúng. Điều nhiều người cùng gặp mới là điểm yếu cấu trúc.',
      c:'Không đúng về cách nền tảng hoạt động.',
      d:'Độ dài không phải lý do.'} },
  { type:'mcq', stem:'Nếu đối thủ lớn cũng tung ra gói “giới hạn hội viên”, điều gì dễ xảy ra với họ?',
    options:[{k:'a',t:'Họ sẽ thắng ngay vì có nhiều cơ sở và nhiều tiền hơn'},{k:'b',t:'Khách sẽ không tin vì họ đã quen chuỗi đó đông'},
             {k:'c',t:'Gói đó bị giới hạn quy mô, khó thành chủ lực của họ'},{k:'d',t:'Khách của bạn sẽ chuyển hết sang họ trong một tháng'}],
    answer:'c', why:{a:'Có tiền nhưng mô hình của họ cần đông hội viên.',
      b:'Có thể một phần, nhưng lý do sâu hơn là kinh tế của mô hình.',
      c:'Đúng. Họ làm được ở vài nơi, nhưng làm đại trà là tự cắt doanh thu.',
      d:'Suy đoán quá mức, không có căn cứ.'} },
  { type:'mcq', stem:'Mã hoá đánh giá của đối thủ: 64 nhắc đông chờ máy ở mọi cơ sở, 9 nhắc một lễ tân thô lỗ ở một cơ sở. Nên lấy gì làm nền cho định vị?',
    options:[{k:'a',t:'Lễ tân thô lỗ, vì phàn nàn về con người gây ấn tượng mạnh nhất'},{k:'b',t:'Cả hai ngang nhau, vì đều là phàn nàn thật của khách hàng'},
             {k:'c',t:'Không cái nào, vì đánh giá trên mạng không đại diện được cho khách'},{k:'d',t:'Chuyện đông chờ máy, vì lặp lại và gắn với mô hình nhiều hội viên'}],
    answer:'d', why:{a:'Một cơ sở, 9 đánh giá là lỗi vận hành lẻ, đối thủ đào tạo lại là xong.',
      b:'Phàn nàn có thật chưa đủ; phải xét tần suất và việc nó có gắn với cấu trúc hay không.',
      c:'Đánh giá có thiên lệch nhưng 64/200 lặp lại là tín hiệu đủ mạnh để kiểm chứng tiếp, không phải để bỏ.',
      d:'Đúng. Lặp lại nhiều và gắn với mô hình sống nhờ đông hội viên, nên khó sửa mà không tự cắt doanh thu.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:ob04-06', skill:'measure', read:'7 phút', t:'Đối thủ giảm giá 20% — bạn có nên giảm theo?',
  situation:'Bạn bán bột giặt túi 3kg giá 150.000đ, chi phí biến đổi (hàng, bao bì, vận chuyển) 90.000đ mỗi túi, bán 2.000 túi mỗi tháng. Đối thủ chính vừa giảm 20% trong một tháng. Đội bán hàng hoảng và muốn giảm theo ngay 20%. Bạn cần tính trước khi trả lời.',
  concept:{ name:'Doanh số cần thêm để bù giảm giá',
    body:'Giảm giá cắt thẳng vào <b>lãi gộp trên mỗi đơn vị</b> (giá − chi phí biến đổi), không phải vào doanh thu. Muốn giữ tổng lãi gộp như cũ, số lượng bán phải tăng theo tỉ lệ: lãi cũ ÷ lãi mới. Biên lãi càng mỏng, giảm giá càng đắt. Trước khi giảm theo, hãy hỏi: đợt giảm của đối thủ kéo dài bao lâu, và khách của mình có thật sự chuyển đi không.' },
  example:'Lãi gộp mỗi túi hiện tại: 150.000 − 90.000 = 60.000đ. Giảm 20% còn 120.000đ, lãi gộp chỉ còn 30.000đ — mất một nửa. Tổng lãi gộp cũ: 2.000 × 60.000 = 120 triệu. Để giữ 120 triệu với lãi 30.000đ mỗi túi, cần bán 4.000 túi, tức gấp đôi. Giảm 20% giá đòi tăng 100% sản lượng. Thay vào đó, bạn tặng thêm túi nhỏ trị giá vốn 10.000đ cho khách quen: lãi còn 50.000đ, chỉ cần bán 2.400 túi.',
  takeaway:'Giảm giá theo đối thủ là giảm lãi trên mỗi đơn vị — hãy tính sản lượng cần bù trước khi quyết.',
  points:["Giảm giá cắt vào phần lãi trên mỗi túi, còn chi phí biến đổi giữ nguyên. Phần giá giảm ăn thẳng vào lãi, chứ không phải vào doanh thu như nhiều người tưởng.","Biên lãi càng mỏng thì số lượng cần bù càng lớn, vì mỗi đơn vị bán thêm chỉ đóng góp ít. Hai sản phẩm cùng giảm 20% có thể cần mức bù rất khác.","Quà tặng cho khách quen nhắm vào nhóm có khả năng chuyển đi, nên chi phí chỉ tính trên người nhận. Giảm giá chung thì tặng cả những khách vốn đã mua."],
  counter:"Biến thể: đối thủ giảm 20% không chỉ một tháng mà giữ mức đó kéo dài, và khách của bạn bắt đầu rời đi rõ rệt. Nếu chỉ tặng quà, lượng bán có thể rơi xuống dưới mức bù được. Dấu hiệu nhận ra: số túi bán hằng tuần giảm liên tục, khách cũ hỏi vì sao đắt hơn, tỉ lệ mua lại tụt. Khi đó phải so lãi mất khi giảm theo với lãi mất khi mất khách.",
  deeper:"Người làm nghề hỏi ngược lại: nếu đối thủ giảm vì nhà máy rẻ hơn thì giá đó sẽ ở lại, còn nếu giảm cho một đợt thì chỉ cần chịu qua tháng. Đánh đổi nằm ở sản lượng và vị trí trên kệ, vì mất vài tuần có thể mất cả chỗ trưng bày. Khái niệm kề cận là điểm hoà vốn và độ co giãn của cầu theo giá. Tín hiệu theo dõi là số khách mua lại trong tháng đối thủ giảm. Phép kiểm tra trong tuần: <b>lập bảng lãi mỗi túi ở ba mức giá</b>, rồi tính số túi cần bán để giữ 120 triệu ở từng mức.",
  apply:'Lấy một sản phẩm có giá và chi phí bạn biết. Tính số lượng cần bán thêm nếu giảm 10%, rồi nói trong 60 giây có đáng không.',
  mistakes:['Nghĩ giảm 20% giá chỉ cần bán thêm 20% là hoà.','Phản ứng ngay trước khi biết đợt giảm của đối thủ kéo dài bao lâu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: giảm giá 20% khi biên lãi gộp là 40% thì phải bán thêm khoảng bao nhiêu để giữ lãi?',
    options:[{k:'a',t:'Khoảng 20%, bằng đúng mức giảm giá đã đưa ra'},{k:'b',t:'Khoảng 25%, vì giá mới thấp hơn giá cũ một phần tư'},
             {k:'c',t:'Khoảng 50%, vì biên lãi chỉ mất đi một nửa'},{k:'d',t:'Khoảng 100%, vì lãi mỗi đơn vị giảm một nửa'}],
    answer:'d', why:{a:'Nhầm giữa giảm giá và giảm lãi.',
      b:'Vẫn tính trên doanh thu, không phải lãi.',
      c:'Lãi còn một nửa thì phải bán gấp đôi, tức thêm 100%, không phải 50%.',
      d:'Đúng. Lãi 60.000 còn 30.000 thì sản lượng phải gấp đôi.'} },
  { type:'mcq', stem:'Đối thủ giảm 20% trong một tháng. Bạn chọn phản ứng nào?',
    options:[{k:'a',t:'Giảm ngay 20% cho khách trong tháng để giữ lấy thị phần'},{k:'b',t:'Giữ giá, tặng quà nhỏ cho khách quen và theo dõi số bán'},
             {k:'c',t:'Giảm sâu hơn, 25%, để kéo cả khách của đối thủ'},{k:'d',t:'Tăng giá để khẳng định chất lượng cao hơn họ'}],
    answer:'b', why:{a:'Cần gấp đôi sản lượng mới giữ được lãi.',
      b:'Đúng. Giữ khách quen với chi phí thấp, chờ dữ kiện xem khách có thật sự rời đi.',
      c:'Mở chiến tranh giá, lãi còn mỏng hơn nữa.',
      d:'Đi ngược thời điểm, dễ đẩy khách sang đối thủ.'} },
  { type:'calc', stem:'Giá 150.000đ, chi phí biến đổi 90.000đ, đang bán 2.000 túi/tháng. Nếu giảm giá còn 120.000đ, cần bán bao nhiêu túi để giữ nguyên tổng lãi gộp?',
    unit:'túi', ans:4000, tol:1, wrong:[[2400,'GIAM_GIA_QUEN_BIEN'],[2500,'GIAM_GIA_QUEN_BIEN'],[1333,'QUEN_CHI_PHI_BIEN_DOI']], errors:['GIAM_GIA_QUEN_BIEN','QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Tổng lãi gộp cũ = 2.000 × (150.000 − 90.000) = 120 triệu.','Lãi mỗi túi mới = 120.000 − 90.000 = 30.000đ.','120.000.000 ÷ 30.000 = <b>4.000 túi</b>.'] },
  { type:'calc', stem:'Giữ giá 150.000đ, tặng quà giá vốn 10.000đ mỗi túi (chi phí biến đổi thành 100.000đ). Cần bán bao nhiêu túi để giữ tổng lãi gộp 120 triệu?',
    unit:'túi', ans:2400, tol:1, wrong:[[2000,'QUEN_CHI_PHI_KHUYEN_MAI'],[1200,'SAI_TINH_TOAN']], errors:['QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Lãi mỗi túi = 150.000 − 100.000 = 50.000đ.','120.000.000 ÷ 50.000 = <b>2.400 túi</b>.'] },
  { type:'mcq', stem:'Tình huống mới: đối thủ giảm giá vĩnh viễn nhờ nhà máy mới rẻ hơn. Câu hỏi quan trọng nhất lúc này là gì?',
    options:[{k:'a',t:'Làm sao để giảm giá sâu hơn họ trong tuần này'},{k:'b',t:'Làm sao chạy thêm quảng cáo nhiều hơn họ'},
             {k:'c',t:'Nhóm khách nào sẵn lòng trả giá cao hơn và vì sao'},{k:'d',t:'Có nên kiện đối thủ vì bán phá giá hay không'}],
    answer:'c', why:{a:'Đấu giá với người có chi phí thấp hơn là thua chắc.',
      b:'Quảng cáo không giải quyết chênh lệch chi phí.',
      c:'Đúng. Khi không thể thắng bằng giá, phải tìm lý do để khách trả thêm.',
      d:'Giá thấp nhờ chi phí thấp không phải phá giá.'} },
  { type:'mcq', stem:'Vì sao quà tặng cho khách quen thường rẻ hơn giảm giá cho mọi người?',
    options:[{k:'a',t:'Vì quà tặng không bị tính vào chi phí bán hàng nên không làm giảm biên lãi'},{k:'b',t:'Vì chi phí quà được tính theo giá vốn, nhỏ hơn mức giảm'},
             {k:'c',t:'Vì khách mới không thích quà nên không lấy'},{k:'d',t:'Vì quà tặng được sàn thương mại điện tử tài trợ'}],
    answer:'b', why:{a:'Quà vẫn là chi phí, phải tính vào.',
      b:'Đúng. Quà có giá trị cảm nhận cao hơn giá vốn; giảm 30.000đ thì mất đúng 30.000đ.',
      c:'Không có căn cứ.',
      d:'Không phải lúc nào cũng vậy.'} },
  { type:'mcq', stem:'Trước khi phản ứng với đợt giảm giá của đối thủ, dữ kiện nào nên xem đầu tiên?',
    options:[{k:'a',t:'Số bán hằng ngày của mình có thật sự đang giảm không'},{k:'b',t:'Đối thủ đã chi bao nhiêu tiền cho đợt quảng cáo này'},
             {k:'c',t:'Người nổi tiếng nào đang giới thiệu cho đối thủ'},{k:'d',t:'Bao bì mới của đối thủ khác bao bì cũ ở điểm nào'}],
    answer:'a', why:{a:'Đúng. Nếu khách không rời đi, không có gì phải bù.',
      b:'Bạn khó biết con số này và nó không cho biết tác động lên bạn.',
      c:'Không liên quan trực tiếp tới quyết định giá.',
      d:'Không liên quan tới đợt giảm giá.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:ob04-07', skill:'insight', read:'6 phút', t:'Một đối thủ mới vừa vào ngành — lo hay chưa cần lo?',
  situation:'Bạn làm cho một thương hiệu nước mắm đóng chai bán ở siêu thị phía Nam. Một thương hiệu mới ra mắt rầm rộ trên TikTok với 3 triệu lượt xem video đầu tiên. Sếp lo lắng, muốn tăng ngân sách quảng cáo gấp đôi ngay tháng sau.',
  concept:{ name:'Ba câu hỏi đo sức đe doạ của người mới',
    body:'Tiếng ồn không bằng sức đe doạ. Hỏi ba câu: (1) <b>Họ lấy khách của ai</b> — cùng nhóm khách của bạn hay nhóm khác? (2) <b>Họ có mặt ở đâu khách mua</b> — độ phủ điểm bán thật sự? (3) <b>Khách có mua lại không</b> — thử một lần hay thành thói quen? Người mới chỉ đáng lo khi cả ba đều nghiêng về phía họ. Lượt xem là câu trả lời cho câu hỏi khác: khách có biết họ không.' },
  example:'Kiểm tra 20 siêu thị bạn có hàng: người mới có mặt ở 3 nơi, tức 15%. Họ bán chủ yếu online với chai nhỏ giá cao, nhắm người trẻ nấu ăn theo công thức. Khách của bạn là các bà nội trợ mua chai 1 lít ở siêu thị. Lúc này họ chưa lấy khách của bạn. Việc đúng: theo dõi hằng tháng độ phủ của họ và tỉ lệ mua lại qua đánh giá trên sàn, thay vì tăng gấp đôi ngân sách ngay.',
  takeaway:'Lượt xem cho biết người mới ồn đến đâu; độ phủ và mua lại mới cho biết họ nguy hiểm đến đâu.',
  points:["Lượt xem đo độ ồn, không đo việc khách có cầm sản phẩm lên khỏi kệ hay không. Muốn đo sức đe doạ phải đến nơi tiền đổi chủ: điểm bán và lần mua sau.","Cạnh tranh chỉ xảy ra khi hai bên cùng nhắm một nhóm khách, cùng nhu cầu và cùng nơi mua. Thiếu một trong ba, họ có thể nổi tiếng mà vẫn chưa chạm tới bạn.","Mua lại là phép thử của thời gian. Người mới có thể thắng một lần vì tò mò; chỉ khi khách quay lại thì họ mới giành được thói quen, thứ bạn đang giữ."],
  counter:"Biến thể: người mới tung ra chai 1 lít giá thấp, và độ phủ nhích lên từ 3 siêu thị sang nhiều nơi hơn chỉ trong vài tuần. Khi đó ba câu trả lời đổi nhanh. Dấu hiệu nhận ra: độ phủ tăng đều mỗi tháng, đánh giá nhắc chuyện mua lại, doanh số chai 1 lít của bạn tại các điểm đó giảm. Khung này chỉ là ảnh chụp, đừng dừng ở lần đầu.",
  deeper:"Người làm nghề nhớ rằng đo sức đe doạ không phải để phản ứng ngay, mà để chọn thời điểm phản ứng. Phản ứng sớm thì tốn tiền, phản ứng muộn thì mất chỗ trên kệ; đánh đổi nằm giữa hai điều đó. Khái niệm kề cận là độ phủ phân phối, tỉ lệ mua lại và phân khúc khách. Tín hiệu theo dõi là số điểm bán có người mới và nhóm khách họ nhắm có dịch sang phía bạn không. Phép kiểm tra trong tuần: <b>lập bảng ba cột cho người mới</b>, gồm lấy khách của ai, có ở đâu, mua lại ra sao, rồi đánh dấu cột còn thiếu dữ kiện.",
  apply:'Chọn một thương hiệu mới nổi bạn thấy gần đây. Trả lời ba câu hỏi trong 60 giây: lấy khách của ai, có ở đâu, khách có mua lại không.',
  mistakes:['Đo sức đe doạ bằng lượt xem và độ ồn trên mạng.','Phản ứng bằng tăng ngân sách trước khi biết người mới nhắm khách nào.'],
  q:[
  { type:'mcq', stem:'Đoán trước: dấu hiệu nào cho thấy người mới thật sự nguy hiểm với bạn?',
    options:[{k:'a',t:'Video ra mắt của họ đạt vài triệu lượt xem'},{k:'b',t:'Họ được nhiều báo chí viết bài giới thiệu'},
             {k:'c',t:'Họ có mặt ở siêu thị của bạn và khách mua lại'},{k:'d',t:'Họ được một quỹ đầu tư lớn rót vốn vào'}],
    answer:'c', why:{a:'Lượt xem đo nhận biết, không đo doanh số.',
      b:'Truyền thông tạo tiếng vang, không phải khách thật.',
      c:'Đúng. Có mặt nơi khách của bạn mua và được mua lại là dấu hiệu đe doạ thật.',
      d:'Vốn là tiềm lực, chưa phải hành vi khách.'} },
  { type:'mcq', stem:'Sếp muốn tăng gấp đôi ngân sách ngay. Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý tăng gấp đôi ngay để không bị người mới vượt mặt trên kệ siêu thị lẫn trên mạng'},{k:'b',t:'Giảm giá chai 1 lít để giữ khách ở siêu thị'},
             {k:'c',t:'Làm video TikTok tương tự để đáp trả người mới'},{k:'d',t:'Theo dõi độ phủ và mua lại hằng tháng, phản ứng khi có ngưỡng'}],
    answer:'d', why:{a:'Chi thêm khi chưa có bằng chứng họ lấy khách của bạn.',
      b:'Giảm lãi để đối phó một mối đe doạ chưa có.',
      c:'Chạy theo sân chơi của họ, nơi khách của bạn không có mặt.',
      d:'Đúng. Đặt ngưỡng rõ, ví dụ khi họ có mặt ở trên 30% điểm bán.'} },
  { type:'calc', stem:'Người mới có mặt ở 3 trong 20 siêu thị bạn đang bán. Độ phủ của họ trên hệ thống của bạn là bao nhiêu phần trăm?',
    unit:'%', ans:15, tol:0.1, wrong:[[666.7,'SAI_MAU_SO'],[3,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Độ phủ = số điểm có hàng ÷ tổng số điểm kiểm tra.','3 ÷ 20 = 0,15 = <b>15%</b>.'] },
  { type:'mcq', stem:'Tình huống mới: một hãng khăn giấy mới bán giá rẻ hơn 30% ở đúng các chợ và tạp hoá bạn đang phủ. Đánh giá sao?',
    options:[{k:'a',t:'Đe doạ cao: cùng khách, cùng điểm bán, lý do mua rõ'},{k:'b',t:'Đe doạ thấp: hãng mới thường chết sau vài tháng'},
             {k:'c',t:'Đe doạ thấp: khách tạp hoá rất trung thành với hãng cũ'},{k:'d',t:'Chưa thể nói vì họ chưa có quảng cáo trên mạng'}],
    answer:'a', why:{a:'Đúng. Hai trong ba câu đã nghiêng về họ; cần theo dõi mua lại sát sao.',
      b:'Một định kiến, không phải dữ kiện.',
      c:'Khăn giấy là hàng ít gắn bó; giá rẻ 30% dễ kéo khách.',
      d:'Không cần quảng cáo khi đã nằm sẵn nơi khách mua.'} },
  { type:'mcq', stem:'Vì sao “khách có mua lại không” là câu hỏi quan trọng?',
    options:[{k:'a',t:'Vì mua lại giúp người mới được sàn thương mại ưu tiên'},{k:'b',t:'Vì dùng thử một lần chưa làm bạn mất khách lâu dài'},
             {k:'c',t:'Vì người mới thường không có ngân sách chạy tiếp'},{k:'d',t:'Vì người mua lại thường để lại đánh giá năm sao'}],
    answer:'b', why:{a:'Có thể đúng một phần nhưng không phải lý do chính.',
      b:'Đúng. Mất khách thật là khi khách đổi thói quen, không phải khi họ tò mò thử.',
      c:'Không có căn cứ chung.',
      d:'Không đúng; mua lại không đồng nghĩa với đánh giá.'} },
  { type:'mcq', stem:'Bạn có thể ước lượng tỉ lệ mua lại của người mới từ nguồn công khai nào?',
    options:[{k:'a',t:'Số lượt xem trung bình trên các video TikTok của họ'},{k:'b',t:'Số lượng bài báo nhắc tên họ trong tháng qua'},
             {k:'c',t:'Đánh giá trên sàn có nội dung “mua lần thứ hai”'},{k:'d',t:'Số người theo dõi trên fanpage chính thức của họ'}],
    answer:'c', why:{a:'Lượt xem không nói gì về mua lại.',
      b:'Báo chí đo độ ồn.',
      c:'Đúng. Đánh giá nhắc mua lại là tín hiệu công khai gần nhất.',
      d:'Theo dõi không phải là mua.'} },
  { type:'mcq', stem:'Người mới nhắm người trẻ nấu ăn theo công thức, còn bạn bán cho nội trợ. Nên hiểu thế nào?',
    options:[{k:'a',t:'Họ đang lấy khách của bạn nhưng dưới một vỏ khác, nên cần đáp trả ngay lập tức'},{k:'b',t:'Họ nên được bỏ qua vì thuộc nhóm khách khác'},
             {k:'c',t:'Bạn nên đổi ngay sang nhắm người trẻ như họ'},{k:'d',t:'Lúc này họ mở nhóm khách mới, chưa chạm khách bạn'}],
    answer:'d', why:{a:'Không có dữ kiện họ lấy khách nội trợ.',
      b:'Người trẻ hôm nay có thể thành người nội trợ ngày mai; cần theo dõi.',
      c:'Bỏ nhóm khách đang mang lại doanh thu là rủi ro lớn.',
      d:'Đúng. Theo dõi, nhưng chưa phải là mối đe doạ trực tiếp.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:ob04-08', skill:'comm', read:'6 phút', t:'Bảng so sánh đối thủ một trang: giữ gì, bỏ gì?',
  situation:'Bạn vừa làm xong nghiên cứu đối thủ cho một thương hiệu balo học sinh: 40 trang slide về 6 đối thủ. Giám đốc chỉ có 10 phút trước cuộc họp ngân sách và nói: “Cho anh một trang, anh cần biết mình thắng ở đâu, thua ở đâu.”',
  concept:{ name:'Bảng so sánh một trang',
    body:'Một bảng tốt có <b>hàng là tiêu chí khách dùng để chọn</b>, rút từ review và phỏng vấn (khách hay khen chê điều gì khi so hãng) và xếp theo số người nhắc, không từ danh sách tính năng của hãng mình. <b>Cột là 3–4 đối thủ quan trọng nhất</b>, tức hãng khách thật sự cân nhắc cùng bạn, và bạn. Mỗi ô là một dữ kiện ngắn có nguồn, không phải tính từ. Khi hãng không công bố, ghi “không công bố” hoặc một ước lượng có nhãn, đừng điền số đoán như số thật. Dưới bảng là ba dòng: mình thắng ở đâu, thua ở đâu, đề xuất gì. Dòng đề xuất phải đủ rõ để người ra quyết định hành động ngay; mọi thứ khác vào phụ lục.' },
  example:'Nhóm giữ 4 đối thủ chiếm khoảng 80% doanh số ngành trên sàn (số minh hoạ). Từ 20 review: 14 người nhắc trọng lượng, 9 chống thấm, 7 bảo hành; màu sắc và tên hãng chỉ 3 và 2 người nên bị loại. Thêm giá (390.000–690.000đ) và độ phủ nhà sách từ dữ liệu bán hàng, thành 5 hàng. Ô “trọng lượng” ghi 450g, không ghi “nhẹ”; ô bảo hành của hãng B ghi “không công bố”. Ba dòng kết: thắng về trọng lượng và bảo hành 24 tháng; thua về độ phủ nhà sách (12 so với 45 điểm của hãng dẫn đầu); đề xuất dồn ngân sách vào mở điểm bán mùa tựu trường.',
  takeaway:'Một trang: tiêu chí của khách, dữ kiện thay cho tính từ, và ba dòng thắng – thua – đề xuất.',
  apply:'Chọn hai sản phẩm bạn đang cân nhắc mua. Làm bảng 4 tiêu chí, rồi nói trong 60 giây: cái nào thắng, ở đâu.',
  mistakes:['Viết tính từ (“tốt”, “đẹp”) trong ô thay cho con số.','Đưa mọi đối thủ và mọi tiêu chí vào để chứng tỏ đã làm kỹ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì khiến bảng so sánh đối thủ khó dùng nhất với người ra quyết định?',
    options:[{k:'a',t:'Bảng thiếu màu sắc và biểu tượng cho sinh động'},{k:'b',t:'Bảng có quá nhiều dòng, không có kết luận'},
             {k:'c',t:'Bảng chỉ so sánh ba hoặc bốn đối thủ chính'},{k:'d',t:'Bảng không có logo của từng đối thủ ở trên'}],
    answer:'b', why:{a:'Trình bày là thứ yếu.',
      b:'Đúng. Người ra quyết định cần biết “vậy thì sao”.',
      c:'Chọn 3–4 đối thủ chính là điểm tốt.',
      d:'Logo không giúp ra quyết định.'} },
  { type:'mcq', stem:'Bản nháp một trang đã có 4 cột đối thủ, 5 hàng tiêu chí và mọi ô đều có số. Giám đốc đọc xong vẫn hỏi: “Vậy anh cần làm gì?”. Bạn thêm gì?',
    options:[{k:'a',t:'Một dòng đề xuất nói rõ nên dồn ngân sách vào đâu'},{k:'b',t:'Một cột đối thủ mới ra mắt để bảng đầy đủ hơn'},
             {k:'c',t:'Vài hàng tiêu chí nữa để thấy nhiều khía cạnh hơn'},{k:'d',t:'Phụ lục chi tiết từng ô dữ kiện kèm nguồn đo'}],
    answer:'a', why:{a:'Đúng. Bảng đủ dữ kiện nhưng thiếu thứ người ra quyết định cần: đề xuất biến so sánh thành hành động.',
      b:'Thêm cột làm bảng loãng hơn, và câu hỏi “làm gì” vẫn chưa được trả lời.',
      c:'Thêm hàng cho thấy nhiều thứ hơn nhưng vẫn không nói thắng, thua, làm gì.',
      d:'Phụ lục tốt cho ai muốn kiểm chứng, không giúp giám đốc quyết định trong 10 phút.'} },
  { type:'calc', stem:'Hãng bạn có 12 điểm bán ở nhà sách, hãng dẫn đầu có 45. Độ phủ của bạn bằng bao nhiêu phần trăm của hãng dẫn đầu?',
    unit:'%', ans:26.7, tol:0.2, wrong:[[375,'SAI_MAU_SO'],[33,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = điểm bán của bạn ÷ điểm bán của hãng dẫn đầu.','12 ÷ 45 ≈ 0,267 = <b>26,7%</b>.'] },
  { type:'mcq', stem:'Hãng B không công bố thời gian bảo hành; chỉ có một review nói hãng này từng đổi cho khách khi hỏng. Ô bảo hành của B ghi gì?',
    options:[{k:'a',t:'“Tốt”, vì một review nói hãng này đổi cho khách khi hỏng'},{k:'b',t:'“24 tháng”, suy từ mặt bằng chung của các hãng cùng tầm giá'},
             {k:'c',t:'“Để trống”, vì không có số thì không nên đưa vào bảng'},{k:'d',t:'“Không công bố”, kèm ghi chú nguồn đã tra và review nếu cần'}],
    answer:'d', why:{a:'Tính từ dựa trên một review không so được với số tháng của hãng khác.',
      b:'Số suy đoán không nhãn trông như dữ kiện thật; người đọc sẽ ra quyết định dựa trên con số không ai kiểm chứng.',
      c:'Ô trống không cho biết là chưa tìm hay hãng không có; thiếu dữ kiện cũng là thông tin.',
      d:'Đúng. Ghi rõ là không công bố, kèm nguồn đã tra: người đọc biết đây là chỗ hở, không phải chỗ hãng B yếu hay mạnh.'} },
  { type:'mcq', stem:'Tình huống mới: bảng cho thấy bạn thắng 4/5 tiêu chí nhưng thua về độ phủ. Dòng đề xuất nên nói gì?',
    options:[{k:'a',t:'Mở thêm điểm bán, vì sản phẩm tốt mà khách không thấy'},{k:'b',t:'Tăng quảng cáo nói về 4 điểm mạnh đang có để khách nhớ tới thương hiệu nhiều hơn'},
             {k:'c',t:'Cải tiến sản phẩm thêm một tiêu chí nữa'},{k:'d',t:'Giảm giá để bù cho việc khó tìm mua'}],
    answer:'a', why:{a:'Đúng. Điểm nghẽn là khách không tìm thấy hàng.',
      b:'Quảng cáo tạo nhu cầu, nhưng khách vẫn không có chỗ mua.',
      c:'Sản phẩm đã thắng; vấn đề nằm ở chỗ khác.',
      d:'Giảm lãi mà không giải quyết chuyện có mặt.'} },
  { type:'mcq', stem:'Nên chọn 3–4 đối thủ nào cho bảng?',
    options:[{k:'a',t:'Những hãng nổi tiếng nhất trên mạng xã hội'},{k:'b',t:'Những hãng khách của bạn hay cân nhắc cùng lúc'},
             {k:'c',t:'Những hãng giá rẻ nhất trong ngành hàng'},{k:'d',t:'Những hãng mà giám đốc hay nhắc tới trong họp'}],
    answer:'b', why:{a:'Nổi tiếng không đồng nghĩa với cạnh tranh trực tiếp khách của bạn.',
      b:'Đúng. Đối thủ quan trọng là hãng nằm cùng danh sách cân nhắc của khách.',
      c:'Có thể không cùng nhóm khách.',
      d:'Ý kiến nội bộ nên được kiểm chứng bằng hành vi khách.'} },
  { type:'mcq', stem:'Từ 20 review: 14 nhắc trọng lượng, 9 nhắc chống thấm, 7 nhắc bảo hành, 3 nhắc màu sắc, 2 nhắc tên thương hiệu. Bảng đã có hàng giá và độ phủ, còn đúng 3 hàng cho tiêu chí từ review. Bạn chọn hàng nào?',
    options:[{k:'a',t:'Màu sắc, tên thương hiệu và bảo hành, vì dễ tìm số liệu nhất'},{k:'b',t:'Trọng lượng, bảo hành và màu sắc, vì là các điểm mình đang thắng'},
             {k:'c',t:'Trọng lượng, chống thấm và bảo hành, vì được nhiều người nhắc nhất'},{k:'d',t:'Trọng lượng, chống thấm và tên thương hiệu, vì thương hiệu quyết định giá'}],
    answer:'c', why:{a:'Dễ tìm số liệu không có nghĩa khách dùng để chọn; hai mục này chỉ 3 và 2 người nhắc.',
      b:'Chọn theo điểm mình mạnh là thiên vị: chống thấm có 9 người nhắc nhưng bị bỏ, còn màu sắc chỉ 3 người.',
      c:'Đúng. Ba mục được nhắc nhiều nhất là thứ khách thật sự dùng để so, đủ để bảng gọn mà vẫn trúng.',
      d:'Tên thương hiệu chỉ 2 người nhắc và không phải thứ khách so giữa các hãng ở đây; bỏ qua bảo hành 7 người nhắc.'} },
  ]},

/* ------------------------------------------------------------------ 09 */
{ id:'B:ob04-09', skill:'brand', read:'6 phút', t:'Học từ đối thủ đến đâu thì thành sao chép?',
  situation:'Bạn làm cho một thương hiệu trà đóng chai mới. Hãng dẫn đầu vừa thành công với chiến dịch in tên người lên nhãn chai. Trong buổi họp, một bạn đề xuất: “Mình làm y vậy nhưng in biệt danh, rẻ hơn 20%.” Bạn cần phân biệt thứ nên học và thứ không nên chép.',
  concept:{ name:'Học nguyên lý, không chép hình thức',
    body:'Mỗi cách làm thành công có hai lớp: <b>hình thức</b> (in tên lên chai) và <b>nguyên lý</b> bên dưới (khách thích thấy mình trong sản phẩm, và thích chia sẻ điều mang tính cá nhân). Chép hình thức làm khách nhớ tới hãng đã làm trước. Để rút nguyên lý, hỏi “vì sao khách phản ứng?” vài lần liên tiếp rồi thử liệt kê ba hình thức khác cùng phục vụ nguyên lý đó. Chép nguyên bản chỉ hợp lý khi nó là chuẩn ngành khách mặc định đòi hỏi, như ghi hạn dùng hay chứng nhận an toàn.' },
  example:'Hỏi “vì sao khách chụp chai?”: vì thấy tên mình; vì thấy mình được nhìn nhận. Nguyên lý: cá nhân hoá làm khách muốn chia sẻ. Ba hình thức khác: nhãn theo quê, nhãn câu chúc, nhãn gửi tặng người thân. Nhóm chọn nhãn 12 tỉnh thành, hợp định vị “trà vị quê”. Thử ở 30 cửa hàng (số minh hoạ): 18% khách chụp ảnh đăng lên mạng, so với khoảng 5% ở chai thường cùng cửa hàng. Cách làm này dùng cùng nguyên lý nhưng không ai nhầm với hãng dẫn đầu.',
  takeaway:'Hỏi “vì sao nó hiệu quả” rồi trả lời bằng hình thức của riêng bạn, đừng lặp lại “họ đã làm gì”.',
  apply:'Chọn một chiến dịch của đối thủ bạn thấy hay. Nói trong 60 giây: nguyên lý bên dưới là gì, và bạn áp dụng bằng hình thức nào khác.',
  mistakes:['Chép cách làm của đối thủ rồi thay vài chi tiết nhỏ và nghĩ đó là khác biệt.','Từ chối học từ đối thủ vì sợ bị coi là chép.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khi hãng nhỏ làm y hệt chiến dịch nổi tiếng của hãng lớn, khách thường nhớ tới ai?',
    options:[{k:'a',t:'Hãng nhỏ, vì cách làm của họ mới xuất hiện gần đây'},{k:'b',t:'Cả hai hãng như nhau, vì cùng một kiểu chiến dịch'},
             {k:'c',t:'Không hãng nào, vì khách đã quá quen với ý tưởng'},{k:'d',t:'Hãng lớn, vì họ gắn với ý tưởng đó trước'}],
    answer:'d', why:{a:'Mới nhưng không khác thì không được nhớ.',
      b:'Trí nhớ khách gắn ý tưởng với người làm đầu tiên.',
      c:'Có thể nhạt dần, nhưng liên tưởng vẫn thuộc về hãng lớn.',
      d:'Đúng. Bạn đang quảng cáo giúp cho hãng lớn.'} },
  { type:'mcq', stem:'Trước đề xuất “in biệt danh, rẻ hơn 20%”, bạn chọn hướng nào?',
    options:[{k:'a',t:'Đồng ý vì biệt danh khác với tên thật, đủ khác biệt và giá lại rẻ hơn 20%'},{k:'b',t:'Giữ nguyên lý cá nhân hoá, tìm hình thức hợp định vị riêng'},
             {k:'c',t:'Bác bỏ các ý tưởng liên quan đến cá nhân hoá nhãn'},{k:'d',t:'Làm y hệt nhưng tung ra trước mùa cao điểm của họ'}],
    answer:'b', why:{a:'Biệt danh chỉ là biến thể nhỏ của cùng hình thức.',
      b:'Đúng. Học điều đang hiệu quả mà vẫn xây tài sản của riêng mình.',
      c:'Bỏ luôn một nguyên lý đã được chứng minh là lãng phí.',
      d:'Đi trước về thời gian không đổi được việc là bản sao.'} },
  { type:'calc', stem:'Ở 30 cửa hàng thử, có 1.500 khách mua chai nhãn tỉnh thành, 270 người chụp ảnh đăng lên mạng. Tỉ lệ chia sẻ là bao nhiêu phần trăm?',
    unit:'%', ans:18, tol:0.1, wrong:[[555.6,'SAI_MAU_SO'],[9,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = số người chia sẻ ÷ số khách mua.','270 ÷ 1.500 = 0,18 = <b>18%</b>.'] },
  { type:'mcq', stem:'Tình huống mới: đối thủ thành công với gói “dùng thử 7 ngày miễn phí” cho phần mềm. Nguyên lý nên học là gì?',
    options:[{k:'a',t:'Phải miễn phí đúng 7 ngày, con số đối thủ đã dùng'},{k:'b',t:'Miễn phí là cách chính để có khách phần mềm'},
             {k:'c',t:'Giảm rủi ro cho khách trước khi họ trả tiền lần đầu'},{k:'d',t:'Khách phần mềm chủ yếu quan tâm đến giá rẻ nhất'}],
    answer:'c', why:{a:'Đó là hình thức, con số 7 có thể không hợp với bạn.',
      b:'Có nhiều cách giảm rủi ro khác: hoàn tiền, gói nhỏ.',
      c:'Đúng. Nguyên lý là hạ rào cản rủi ro; hình thức có thể khác.',
      d:'Suy diễn quá mức từ một cách làm.'} },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy bạn đang chép hình thức chứ không học nguyên lý?',
    options:[{k:'a',t:'Khách xem xong dễ gọi nhầm tên thành đối thủ'},{k:'b',t:'Chiến dịch dùng cùng một kênh như đối thủ'},
             {k:'c',t:'Chiến dịch nhắm đúng nhóm khách giống đối thủ'},{k:'d',t:'Chiến dịch chạy vào cùng mùa như đối thủ'}],
    answer:'a', why:{a:'Đúng. Khách nhầm là dấu hiệu bạn chưa tạo được điều riêng.',
      b:'Cùng kênh là bình thường.',
      c:'Cạnh tranh cùng khách là chuyện tất nhiên.',
      d:'Mùa vụ là đặc điểm ngành, không phải sao chép.'} },
  { type:'mcq', stem:'Vì sao “từ chối học từ đối thủ” cũng là sai lầm?',
    options:[{k:'a',t:'Vì đối thủ lớn có nhiều dữ liệu nên đáng tin hơn'},{k:'b',t:'Vì pháp luật yêu cầu doanh nghiệp theo dõi đối thủ'},
             {k:'c',t:'Vì đối thủ đã kiểm chứng nên chép lại là cách an toàn nhất'},{k:'d',t:'Vì bỏ qua bằng chứng miễn phí về điều khách đáp lại'}],
    answer:'d', why:{a:'Đối thủ cũng sai; vấn đề là học có chọn lọc.',
      b:'Không có quy định như vậy.',
      c:'Đây là lý do để chép, không phải lý do việc từ chối học là sai; chép nguyên bản còn khiến khách nhầm với hãng đi trước.',
      d:'Đúng. Đối thủ đã trả tiền để thử; bạn học được mà không tốn chi phí.'} },
  { type:'mcq', stem:'Nhãn tỉnh thành có 18% khách chia sẻ, chai thường 5%. Cần kiểm tra điều gì trước khi kết luận nhãn là nguyên nhân?',
    options:[{k:'a',t:'Hãng dẫn đầu có từng công bố tỉ lệ chia sẻ cao hơn 18% không'},{k:'b',t:'Hai loại chai có bán cùng cửa hàng, cùng tuần để so sánh không'},
             {k:'c',t:'Khách có thích màu sắc nhãn tỉnh thành hơn nhãn thường không'},{k:'d',t:'Nhãn có đủ 12 tỉnh thành để khách tìm thấy quê mình không'}],
    answer:'b', why:{a:'So với hãng khác không cho biết nhãn có gây ra chênh lệch ngay trong các cửa hàng này.',
      b:'Đúng. Nếu chai nhãn nằm ở cửa hàng đông khách hơn thì 18% so với 5% chưa nói lên nhãn; cần đối chứng cùng điều kiện.',
      c:'Màu sắc là một phần của nhãn, chỉ là cơ chế; không loại được yếu tố nhiễu về cửa hàng và thời điểm.',
      d:'Độ phủ lựa chọn có thể ảnh hưởng mức chia sẻ nhưng không giúp kết luận nhân quả.'} },
  ]},

]});
